import JSZip from 'jszip'

export async function generateExportBundle(idea, components, options) {
  const zip = new JSZip()

  const projectName = idea.replace(/[^a-zA-Z0-9]/g, '_').slice(0, 25)
  const folder = zip.folder(projectName)

  const date = new Date().toLocaleDateString('en-US', {
    year: 'numeric', month: 'long', day: 'numeric'
  })

  const totalMin = components.reduce(function(sum, c) {
    const price = c.estimatedPrice || '$5'
    const num = parseInt(price.match(/\d+/)?.[0] || '5')
    return sum + num
  }, 0)

  const totalMax = components.reduce(function(sum, c) {
    const price = c.estimatedPrice || '$15'
    const matches = price.match(/\d+/g) || ['15']
    const num = parseInt(matches[matches.length - 1]) || 15
    return sum + num
  }, 0)

  const componentList = components.map(function(c) {
    return c.name + ' (' + c.category + ')'
  }).join(', ')

  // 1. README.md
  const readmeLines = [
    '# ' + idea,
    '',
    '> Generated by ProtoMind — protomind-ten.vercel.app',
    '',
    '## Overview',
    '',
    'This prototype uses ' + components.length + ' components with an estimated cost of $' + totalMin + ' to $' + totalMax + ' USD.',
    '',
    '## Components',
    '',
    '| Component | Category | Est. Price |',
    '|-----------|----------|------------|',
    ...components.map(function(c) {
      return '| ' + c.name + ' | ' + c.category + ' | ' + (c.estimatedPrice || 'N/A') + ' |'
    }),
    '',
    '## Getting Started',
    '',
    '1. Order all components from the BOM (see BOM.csv)',
    '2. Follow the wiring guide (see WIRING.md)',
    '3. Upload the code to your microcontroller (see code/ folder)',
    '4. Test each component individually before full assembly',
    '',
    '## Safety Notes',
    '',
    '- Always double-check polarity before connecting power',
    '- Never exceed maximum voltage ratings',
    '- Test on breadboard before soldering',
    '- Disconnect power before modifying circuit',
    '',
    '---',
    '',
    '*Generated with ProtoMind on ' + date + '*',
  ]
  folder.file('README.md', readmeLines.join('\n'))

  // 2. BOM.csv
  const bomLines = [
    '"#","Component","Category","Quantity","Est. Min Price","Est. Max Price","Notes"',
    ...components.map(function(c, i) {
      const price = c.estimatedPrice || '$5-15'
      const nums = price.match(/\d+/g) || ['5', '15']
      return '"' + (i + 1) + '","' + c.name + '","' + c.category + '","1","$' + nums[0] + '","$' + (nums[1] || nums[0]) + '",""'
    }),
    '"","","TOTAL","' + components.length + '","$' + totalMin + '","$' + totalMax + '",""',
  ]
  folder.file('BOM.csv', bomLines.join('\n'))

  // 3. WIRING.md
  const wiringLines = [
    '# Wiring Guide — ' + idea,
    '',
    '## Components',
    '',
    componentList,
    '',
    '## Power Connections',
    '',
    '| Component | VCC Pin | GND Pin | Voltage |',
    '|-----------|---------|---------|---------|',
    ...components.filter(function(c) { return c.category !== 'Power' }).map(function(c) {
      const voltage = c.category === 'Microcontroller' ? '5V' : c.category === 'Sensor' ? '3.3V-5V' : '5V'
      return '| ' + c.name + ' | VCC | GND | ' + voltage + ' |'
    }),
    '',
    '## Important Notes',
    '',
    '- Always connect GND before VCC',
    '- Use level shifters when connecting 5V components to 3.3V boards',
    '- Add 100nF decoupling capacitors near each IC power pin',
    '- I2C devices require 4.7kΩ pull-up resistors on SDA and SCL',
    '',
    '## Testing Order',
    '',
    '1. Test power supply voltages with multimeter',
    '2. Connect and test microcontroller alone',
    '3. Add components one by one, testing each',
    '4. Test full system integration last',
    '',
    '*Generated with ProtoMind on ' + date + '*',
  ]
  folder.file('WIRING.md', wiringLines.join('\n'))

  // 4. Arduino code
  const codeLines = [
    '/*',
    ' * ' + idea,
    ' * Generated by ProtoMind — protomind-ten.vercel.app',
    ' * Date: ' + date,
    ' *',
    ' * Components:',
    ...components.map(function(c) { return ' *   - ' + c.name + ' (' + c.category + ')' }),
    ' */',
    '',
    '// Pin Definitions',
    ...components.map(function(c, i) {
      const pinName = c.name.replace(/[^a-zA-Z0-9]/g, '_').toUpperCase() + '_PIN'
      return '#define ' + pinName + ' ' + (i + 2)
    }),
    '',
    '// Libraries',
    '// Add your required libraries here',
    '// Example: #include <DHT.h>',
    '',
    'void setup() {',
    '  Serial.begin(9600);',
    '  Serial.println("' + idea + ' - Starting...");',
    '',
    '  // Initialize components',
    ...components.map(function(c) {
      const pinName = c.name.replace(/[^a-zA-Z0-9]/g, '_').toUpperCase() + '_PIN'
      if (c.category === 'Actuator') return '  pinMode(' + pinName + ', OUTPUT);'
      if (c.category === 'Sensor') return '  // Initialize ' + c.name
      return '  // Setup ' + c.name
    }),
    '',
    '  Serial.println("Setup complete!");',
    '}',
    '',
    'void loop() {',
    '  // Main prototype logic here',
    '',
    ...components.filter(function(c) { return c.category === 'Sensor' }).map(function(c) {
      return '  // Read ' + c.name + '\n  // int value = analogRead(A0);'
    }),
    '',
    '  delay(1000); // Adjust delay as needed',
    '}',
  ]

  const codeFolder = folder.folder('code')
  codeFolder.file('main.ino', codeLines.join('\n'))

  // 5. SPECS.md
  const specsLines = [
    '# Technical Specifications — ' + idea,
    '',
    '## Project Info',
    '',
    '| Parameter | Value |',
    '|-----------|-------|',
    '| Prototype Name | ' + idea + ' |',
    '| Total Components | ' + components.length + ' |',
    '| Est. Cost Range | $' + totalMin + ' — $' + totalMax + ' USD |',
    '| Generated | ' + date + ' |',
    '',
    '## Component Specifications',
    '',
    ...components.map(function(c) {
      return '### ' + c.name + '\n' +
        '- **Category:** ' + c.category + '\n' +
        '- **Price:** ' + (c.estimatedPrice || 'N/A') + '\n' +
        '- **Description:** ' + (c.description || 'No description available') + '\n'
    }),
    '## Safety Checklist',
    '',
    '- [ ] Verify all voltage levels are correct',
    '- [ ] Check all connections for shorts',
    '- [ ] Test individual components before assembly',
    '- [ ] Add appropriate fuses or protection circuits',
    '- [ ] Document any modifications made',
    '',
    '*Generated with ProtoMind on ' + date + '*',
  ]
  folder.file('SPECS.md', specsLines.join('\n'))

  // 6. CHECKLIST.md
  const checklistLines = [
    '# Build Checklist — ' + idea,
    '',
    '## Planning Phase',
    '- [ ] Verify all components are available',
    '- [ ] Order components from BOM.csv',
    '- [ ] Review wiring guide (WIRING.md)',
    '- [ ] Set up development environment',
    '',
    '## Build Phase',
    '- [ ] Assemble circuit on breadboard',
    '- [ ] Test power connections',
    ...components.map(function(c) { return '- [ ] Test ' + c.name }),
    '- [ ] Test full integration',
    '',
    '## Code Phase',
    '- [ ] Upload code from code/ folder',
    '- [ ] Test all sensor readings',
    '- [ ] Test all outputs and actuators',
    '- [ ] Debug any issues',
    '',
    '## Polish Phase',
    '- [ ] Design enclosure',
    '- [ ] Write documentation',
    '- [ ] Take photos of build',
    '- [ ] Share with community',
    '',
    '*Generated with ProtoMind on ' + date + '*',
  ]
  folder.file('CHECKLIST.md', checklistLines.join('\n'))

  // 7. SUMMARY.txt
  const summaryLines = [
    '='.repeat(60),
    'PROTOTYPE EXPORT BUNDLE',
    '='.repeat(60),
    '',
    'Project: ' + idea,
    'Exported: ' + date,
    'Generated by: ProtoMind — protomind-ten.vercel.app',
    '',
    'COMPONENTS (' + components.length + ' total)',
    '-'.repeat(40),
    ...components.map(function(c, i) {
      return (i + 1) + '. ' + c.name + ' (' + c.category + ') — ' + (c.estimatedPrice || 'N/A')
    }),
    '',
    'ESTIMATED COST',
    '-'.repeat(40),
    'Minimum: $' + totalMin + ' USD',
    'Maximum: $' + totalMax + ' USD',
    '',
    'BUNDLE CONTENTS',
    '-'.repeat(40),
    'README.md      — Project overview and getting started',
    'BOM.csv        — Bill of materials with prices',
    'WIRING.md      — Wiring guide and pin connections',
    'SPECS.md       — Technical specifications',
    'CHECKLIST.md   — Build checklist',
    'code/main.ino  — Arduino starter code',
    '',
    '='.repeat(60),
  ]
  folder.file('SUMMARY.txt', summaryLines.join('\n'))

  const blob = await zip.generateAsync({ type: 'blob' })
  return { blob, filename: projectName + '_ProtoMind_Bundle.zip' }
}